mem=$(vm_stat|awk 'NR==2{printf"%.0f",$3*4096/1048576}');[ $mem -gt 80 ]&&echo "ALERT: Memory ${mem}%"&&ps aux -r|head -6||echo "Memory: ${mem}%";echo "CPU: $(ps -A -o %cpu | awk '{s+=$1} END {print s "%"}')";df -h /|awk 'NR==2{print "Disk: "$5}'

